  waiver_block_comment: { kind: "set", add_sql: `INSERT OR IGNORE INTO "waiver_block_comment" ("path", "waiver_line") VALUES (?, ?)`, del_sql: `DELETE FROM "waiver_block_comment" WHERE "path" = ? AND "waiver_line" = ?` },
